WITH latest_match AS (SELECT s.id, s.region, s.opened_date, s.sqft, top1.store_sale_revenue FROM stores s LEFT JOIN LATERAL (SELECT c.revenue AS store_sale_revenue FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT region, DATE_TRUNC('MONTH', opened_date) AS activity_month, STDDEV_SAMP(sqft) AS sqft_stddev, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'East' THEN 1 END), 0), 2) AS sqft_per_east, GROUPING(region) AS gid FROM latest_match GROUP BY GROUPING SETS ((region, DATE_TRUNC('MONTH', opened_date)), (region), ()) ORDER BY region DESC NULLS FIRST
